/** The result of a check: the value, or the rules it breaks. */
export type CheckResult<T> = { readonly ok: true; readonly domain: typeof DOMAIN; readonly value: T } | { readonly ok: false; readonly domain: typeof DOMAIN; readonly failures: readonly Failure[] };

/** The types of the definitions, by name. */
export interface DefinitionTypes {
  readonly role: Role;
  readonly employee_id: EmployeeId;
  readonly manager_id: ManagerId;
  readonly actor_id: ActorId;
  readonly caller: Caller;
  readonly utc_time: UtcTime;
  readonly now: Now;
  readonly submitted_at: SubmittedAt;
  readonly overdue_reported_at: OverdueReportedAt;
  readonly occurred_at: OccurredAt;
  readonly claim_id: ClaimId;
  readonly version: Version;
  readonly state: State;
  readonly currency: Currency;
  readonly total: Total;
  readonly purpose: Purpose;
  readonly reason: Reason;
  readonly idempotency_key: IdempotencyKey;
  readonly category: Category;
  readonly expense_date: ExpenseDate;
  readonly description: Description;
  readonly amount: Amount;
  readonly distance_km: DistanceKm;
  readonly sha256: Sha256;
  readonly media_type: MediaType;
  readonly size_bytes: SizeBytes;
  readonly receipt: Receipt;
  readonly line: Line;
  readonly lines: Lines;
  readonly receipts_in_use: ReceiptsInUse;
  readonly claim: Claim;
  readonly stored_claim: StoredClaim;
  readonly event_id: EventId;
  readonly claim_submitted: ClaimSubmitted;
  readonly claim_withdrawn: ClaimWithdrawn;
  readonly claim_approved: ClaimApproved;
  readonly claim_rejected: ClaimRejected;
  readonly claim_paid: ClaimPaid;
  readonly claim_decision_overdue: ClaimDecisionOverdue;
  readonly draft: Draft;
  readonly draft_edit: DraftEdit;
  readonly change: Change;
  readonly submission: Submission;
  readonly rejection: Rejection;
  readonly lookup: Lookup;
  readonly overdue_check: OverdueCheck;
  readonly submitted: Submitted;
  readonly withdrawn: Withdrawn;
  readonly approved: Approved;
  readonly rejected: Rejected;
  readonly paid: Paid;
  readonly overdue_reported: OverdueReported;
  readonly not_found: NotFound;
  readonly forbidden: Forbidden;
  readonly invalid_state: InvalidState;
  readonly version_conflict: VersionConflict;
  readonly duplicate_receipt: DuplicateReceipt;
}

/** Checks a value against a definition: its structure, then each rule. */
export function check<D extends DefinitionName>(definition: D, value: unknown): CheckResult<DefinitionTypes[D]> {
  const failures: Failure[] = [];
  return CHECKS[definition](value, '', failures) ? { ok: true, domain: DOMAIN, value: value as DefinitionTypes[D] } : { ok: false, domain: DOMAIN, failures };
}

/** What an operation answers: one of its outputs, by name, and its value. */
export interface Answer<O extends string, V> {
  readonly output: O;
  readonly value: V;
}

/** An answer of the core: answer('booking', booking). */
export function answer<O extends string, V>(output: O, value: V): Answer<O, V> {
  return { output, value };
}

/** The answers of create_draft. */
export type CreateDraftAnswer = Answer<"claim", Claim> | Answer<"forbidden", Forbidden> | Answer<"duplicate_receipt", DuplicateReceipt>;

/** The answers of edit_draft. */
export type EditDraftAnswer = Answer<"claim", Claim> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"invalid_state", InvalidState> | Answer<"version_conflict", VersionConflict> | Answer<"duplicate_receipt", DuplicateReceipt>;

/** The answers of submit_claim. */
export type SubmitClaimAnswer = Answer<"submitted", Submitted> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"invalid_state", InvalidState> | Answer<"version_conflict", VersionConflict>;

/** The answers of withdraw_claim. */
export type WithdrawClaimAnswer = Answer<"withdrawn", Withdrawn> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"invalid_state", InvalidState> | Answer<"version_conflict", VersionConflict>;

/** The answers of approve_claim. */
export type ApproveClaimAnswer = Answer<"approved", Approved> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"invalid_state", InvalidState> | Answer<"version_conflict", VersionConflict>;

/** The answers of reject_claim. */
export type RejectClaimAnswer = Answer<"rejected", Rejected> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"invalid_state", InvalidState> | Answer<"version_conflict", VersionConflict>;

/** The answers of mark_paid. */
export type MarkPaidAnswer = Answer<"paid", Paid> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"invalid_state", InvalidState> | Answer<"version_conflict", VersionConflict>;

/** The answers of get_claim. */
export type GetClaimAnswer = Answer<"claim", Claim> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden>;

/** The answers of report_overdue. */
export type ReportOverdueAnswer = Answer<"overdue_reported", OverdueReported> | Answer<"not_found", NotFound> | Answer<"forbidden", Forbidden> | Answer<"invalid_state", InvalidState>;

/** The core: a function for each operation, from its input to one of its answers. */
export interface DomainCore {
  /** Create a draft claim for the employee who calls */
  readonly create_draft: (input: Draft) => CreateDraftAnswer;
  /** Replace the purpose, currency and lines of a draft claim; a rejected claim goes back to DRAFT */
  readonly edit_draft: (input: DraftEdit) => EditDraftAnswer;
  /** Submit a draft claim for a decision */
  readonly submit_claim: (input: Submission) => SubmitClaimAnswer;
  /** Withdraw a submitted claim */
  readonly withdraw_claim: (input: Change) => WithdrawClaimAnswer;
  /** Approve a submitted claim */
  readonly approve_claim: (input: Change) => ApproveClaimAnswer;
  /** Reject a submitted claim with a reason */
  readonly reject_claim: (input: Rejection) => RejectClaimAnswer;
  /** Mark an approved claim paid */
  readonly mark_paid: (input: Change) => MarkPaidAnswer;
  /** Read a claim by its id */
  readonly get_claim: (input: Lookup) => GetClaimAnswer;
  /** Report a claim that waits in SUBMITTED for a decision for 30 days since its last submission, once, with no change of state */
  readonly report_overdue: (input: OverdueCheck) => ReportOverdueAnswer;
}

